import{_ as t,c as o,o as a,aj as n}from"./chunks/framework.D5_XyAxb.js";const h=JSON.parse('{"title":"NeoNephos Community Call","description":"","frontmatter":{"title":"NeoNephos Community Call","date":"2026-10-14","banner":"assets/events/20261014_community_call_banner.svg","bannerMobile":"assets/events/20261014_community_call_banner_mobile.svg","bannerSmall":"assets/events/20261014_community_call_banner_small.svg","backgroundhex":"#889aa4ff","tags":["neonephos","community-call"],"published":true,"sidebar":false,"aside":false,"prev":false,"next":false,"layout":"EventEntryThemeComponent"},"headers":[],"relativePath":"events/2026_10_14_Community_Call.md","filePath":"events/2026_10_14_Community_Call.md"}'),r={name:"events/2026_10_14_Community_Call.md"};function s(i,e,l,c,m,d){return a(),o("div",null,e[0]||(e[0]=[n('<h1 id="neonephos-october-community-call" tabindex="-1">NeoNephos October Community Call <a class="header-anchor" href="#neonephos-october-community-call" aria-label="Permalink to &quot;NeoNephos October Community Call&quot;">​</a></h1><p>It&#39;s been a long time! On October 14th we again bring together the NeoNephos Foundation community in our Community Call! This time, we&#39;ll feature <a href="https://github.com/chantico-project" target="_blank" rel="noreferrer">Chantico</a> to introduce you on what this project is about!</p><blockquote><p>Title: Chantico: energy-aware cloud-native controller Abstract:</p><p>We introduce the energy-aware domain controller, Chantico and its goals, architecture and current functionality. TNO is developing Chantico as part of the Modular Integrated Sustainable Datacenter (MISD) project under the &gt;IPCEI-CIS 8ra Initiative, in orchestration and energy flexibility efforts, and the project is onboarded into NeoNephos.</p><p>This cloud-native monitoring solution consists of a Kubernetes operator which integrates with existing open source software for collecting energy measurements. We monitor devices like PDUs and bare metal servers but also &gt;VMs and other higher-level resources, aggregating data and attributing timeseries to report service consumption. We consider fair distribution algorithms of unallocated overhead between data center operations and tenant &gt;workloads. Chantico also becomes extensible with carbon emission measurements and enables green workload shifting.</p></blockquote><blockquote><p>We present what Chantico is about and end with a demo of the graph-based K8s custom resource models and some use cases.</p></blockquote><p><strong>Zoom Session Link</strong></p><p><a href="https://zoom-lfx.platform.linuxfoundation.org/meeting/98831004509?password=b4844bad-66b2-49d4-b483-7636e6349ff8" target="_blank" rel="noreferrer">https://zoom-lfx.platform.linuxfoundation.org/meeting/98831004509?password=b4844bad-66b2-49d4-b483-7636e6349ff8</a></p><p><a href="https://webcal.prod.itx.linuxfoundation.org/lfx/lfGnr1MCq2lbKUf6f7" target="_blank" rel="noreferrer">Download the iCal file to add this meeting to your calendar.</a></p>',7)]))}const p=t(r,[["render",s]]);export{h as __pageData,p as default};
